import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tokenizer = null;

        String line = reader.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = reader.readLine();
        }
        if (line == null) return;

        tokenizer = new StringTokenizer(line);
        int N = Integer.parseInt(tokenizer.nextToken());
        int M = Integer.parseInt(tokenizer.nextToken());

        int[][] G = new int[N][M];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                    line = reader.readLine();
                    tokenizer = new StringTokenizer(line);
                }
                G[i][j] = Integer.parseInt(tokenizer.nextToken());
            }
        }

        // Configuração 0:
        // Se (i + j) é par => valor deve ser ímpar (1)
        // Se (i + j) é ímpar => valor deve ser par (0)
        //
        // Configuração 1:
        // Se (i + j) é par => valor deve ser par (0)
        // Se (i + j) é ímpar => valor deve ser ímpar (1)

        int cost0 = 0;
        int cost1 = 0;

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                int expectedParity0 = ((i + j) % 2 == 0) ? 1 : 0;
                int currentParity = G[i][j] % 2;

                if (currentParity != expectedParity0) {
                    cost0++;
                } else {
                    cost1++;
                }
            }
        }

        int chosenConfig = (cost0 <= cost1) ? 0 : 1;
        int minCost = Math.min(cost0, cost1);

        StringBuilder sb = new StringBuilder();
        sb.append(minCost).append("\n");

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                int expectedParity;
                if (chosenConfig == 0) {
                    expectedParity = ((i + j) % 2 == 0) ? 1 : 0;
                } else {
                    expectedParity = ((i + j) % 2 == 0) ? 0 : 1;
                }

                int val = G[i][j];
                if (val % 2 != expectedParity) {
                    val++;
                }
                sb.append(val);
                if (j < M - 1) {
                    sb.append(" ");
                }
            }
            sb.append("\n");
        }

        System.out.print(sb);
    }
}
